import {pages,videos,channel} from './content.js';
import {mountMesh} from './mesh.js';
const $=s=>document.querySelector(s),scene=$('#scene'),viewport=$('#viewport');
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const categories=[['about','About Me','PERSON / PERSPECTIVE'],['career','Career Experience','ROLES / EXPERIENCE'],['design','Design Projects','IDEAS / OBJECTS'],['content','Content Creation','FILMS / TECHNOLOGY']];
const marks=['<circle cx="16" cy="10" r="5"/><path d="M6 28v-5a10 10 0 0 1 20 0v5Z"/>','<rect x="4" y="10" width="24" height="18"/><path d="M11 10V5h10v5M4 18h24"/>','<path d="m16 3 13 8v13l-13 7L3 24V11ZM3 11l13 8 13-8M16 19v12"/>','<rect x="3" y="7" width="26" height="19"/><path d="m13 12 8 5-8 5Z"/>'];
const icon=n=>`<svg viewBox="0 0 32 34" aria-hidden="true">${marks[n%4]}</svg>`;
const pad=n=>String(n).padStart(2,'0');
let current='home',previous='home',entry={x:0,y:20};
const mesh=mountMesh($('#mesh'));
function home(){return `<section class="home-slide"><div class="home-coordinate micro">[ ZX / ORIGIN ]<span>00 : 00</span></div><div class="origin-node"><div class="portrait-unit panel"><div class="panel-code"><span>ZX.00</span><span>PORTRAIT</span></div><img src="assets/portrait.jpg" alt="Zac in the ZXTECH studio"><div class="portrait-target" aria-hidden="true"></div><span class="image-index micro">ZAC / SINGAPORE</span></div><div class="identity-unit panel"><div class="panel-code"><span>IDENTITY</span><span>001</span></div><h1>Zac Ong<br>Zhi Xing<span class="title-cursor" aria-hidden="true">_</span></h1><div class="futurist">FUTURIST<span aria-hidden="true">↗</span></div><div class="identity-scale" aria-hidden="true"></div></div></div>${categories.map(([id,title,sub],i)=>`<a class="orbit ${id}" href="#${id}" data-edge="${id}"><div class="orbit-head"><span class="node-number">${pad(i+1)}</span>${icon(i)}<span class="orbit-plus">+</span></div><strong>${title}</strong><span class="micro">${sub}</span></a>`).join('')}<span class="home-instruction micro">SELECT A DIRECTION<span>EXPLORE THE ARCHIVE ↗</span></span></section>`;}
const pageIds=Object.keys(pages);
let mediaIndex=0,noteIndex=0,mapState={x:0,y:0,scale:1};
function path(id){let parts=[],p=pages[id];while(p){parts.unshift([id,p.short||p.title]);id=p.parent;p=pages[id];}return `<div class="slide-path"><a href="#home">ZX</a>${parts.map(([key,title],i)=>`<span class="path-sep">/</span>${i===parts.length-1?`<span aria-current="page">${esc(title)}</span>`:`<a href="#${key}">${esc(title)}</a>`}`).join('')}</div>`;}
function heading(p,id){return `<div class="slide-heading" data-node="hub"><div><span class="micro">${esc(p.sub)}</span><h1 tabindex="-1">${esc(p.short||p.title)}</h1></div><span class="heading-index" aria-hidden="true">${pad(pageIds.indexOf(id)+1)}<small>/ ZX</small></span></div>`;}
function wrapper(id,body,footer=''){return `<section class="slide slide-${pages[id].kind||'project'}">${path(id)}${heading(pages[id],id)}${body}<div class="slide-bottom">${footer||bottom(id)}</div></section>`;}
function bottom(id){const p=pages[id],siblings=pages[p.parent]?.children||[],i=siblings.indexOf(id),next=i>=0?siblings[i+1]:null;return `<a class="back-link" href="#${p.parent}"><span>↖</span> ${p.parent==='home'?'ORIGIN':esc(pages[p.parent]?.title)}</a>${p.related?`<a class="connection-link" href="#${p.related}"><span class="micro">CONNECTED</span>${esc(pages[p.related].short||pages[p.related].title)} <span>↗</span></a>`:next?`<a class="connection-link" href="#${next}"><span class="micro">NEXT</span>${esc(pages[next].title)} <span>→</span></a>`:'<span class="micro footer-coordinate">ZX / PERSONAL ARCHIVE</span>'}`;}
function firstImage(p){return p.cover||p.image||p.images?.[0]||(p.kind==='video'?`assets/${p.id}.jpg`:null);}
function spreadLayout(count,width,height){
 const mobile=width<650,ratio=mobile?1.42:1.78;
 const base=Math.min(width*(mobile?.44:.40),height*ratio*.34,410);
 const anchors=count===3?[[.23,.24,.96],[.75,.40,1],[.43,.78,1.02]]:[[.24,.22,.96],[.75,.40,1],[.31,.76,1.02],[.78,.82,.95]];
 const clamp=(v,min,max)=>Math.max(min,Math.min(max,v));
 return anchors.slice(0,count).map(([x,y,size])=>{const w=base*size,h=w/ratio;return {x:clamp(x*width,w*.65,width-w*.65),y:clamp(y*height,h*.67,height-h*.67),w,h};});
}
function branch(id){const p=pages[id];return wrapper(id,`<div class="branch-space spread-space"><div class="branch-cards card-spread count-${p.children.length}">${p.children.map((key,i)=>{const n=pages[key],image=firstImage(n);return `<a class="branch-card panel" href="#${key}" data-node="${key}"><div class="panel-code"><span>${pad(i+1)} / ${n.kind==='branch'?'DIRECTION':p.parent==='home'&&id==='career'?'EXPERIENCE':'PROJECT'}</span><span>↗</span></div><div class="branch-visual">${image?`<img src="${image}" alt="${esc(n.coverAlt||n.captions?.[0]||n.title)}">`:`<div class="abstract-node"><span class="giant-index">${pad(i+1)}</span>${icon(id==='career'?1:2)}</div>`}${n.status?`<span class="status">${n.status}</span>`:''}</div><div class="branch-label"><h2>${esc(n.title)}</h2><p>${esc(n.sub)}</p></div><div class="node-terminal" aria-hidden="true"><span>+</span><i></i><span>⌁</span></div></a>`;}).join('')}</div></div>`);}
function mediaItems(p){return [...(p.images||[p.image].filter(Boolean)).map((src,i)=>({src,title:p.captions?.[i]||p.title,sub:p.mediaSubtitles?.[i],credit:p.mediaCredits?.[i],source:p.mediaSources?.[i]||(i===0?p.source:null)})),...(p.pendingMedia||[])];}
function photoPane(p){
 const items=mediaItems(p),item=items[mediaIndex];
 return `<div class="media-panel panel"><div class="panel-code"><span>${p.status||'VISUAL ARCHIVE'}</span><span>${items.length?`${pad(mediaIndex+1)} / ${pad(items.length)}`:'AWAITING IMAGES'}</span></div><div class="media-screen">${item?.src?`<button class="image-open" data-src="${item.src}" data-caption="${esc(item.title)}" aria-label="Enlarge ${esc(item.title)}"><img src="${item.src}" alt="${esc(item.title)}"><span class="enlarge">EXPAND ↗</span></button>`:`<div class="media-empty"><span class="empty-symbol" aria-hidden="true">[ + ]</span>${item?`<span class="micro">${item.year||''} / SPATIAL DESIGN</span><strong>${esc(item.title)}</strong><span>${esc(item.sub)}</span><small>Photo to add</small>`:`<span>${esc(p.mediaPlaceholder||'Images to add')}</span>`}</div>`}</div><div class="media-caption"><span>${esc(item?.title||p.title)}${item?.sub?`<small>${esc(item.sub)}</small>`:''}${item?.credit?`<small>Photo: ${esc(item.credit)}</small>`:''}</span>${item?.source?`<a href="${item.source.url}" target="_blank" rel="noopener">SOURCE ↗</a>`:''}</div>${items.length>1?`<div class="image-strip"><button data-image-step="-1" aria-label="Previous image">←</button><div class="image-thumbs">${items.map((item,i)=>`<button class="image-thumb ${i===mediaIndex?'active':''} ${item.src?'':'pending-thumb'}" data-image-index="${i}" aria-label="Image ${i+1}: ${esc(item.title)}" aria-pressed="${i===mediaIndex}">${item.src?`<img src="${item.src}" alt="">`:'<b aria-hidden="true">+</b>'}<span>${pad(i+1)}</span></button>`).join('')}</div><button data-image-step="1" aria-label="Next image">→</button></div>`:''}</div>`;
}
function notes(p,titles=p.prompts||['Overview','Process','Reflections']){const selected=p.notes?.[noteIndex],text=selected?.body||(noteIndex===0?p.body:'');return `<section class="note-panel panel"><div class="panel-code"><span>PROJECT NOTES</span><span>${pad(noteIndex+1)} / ${pad(titles.length)}</span></div><div class="note-select" role="tablist" aria-label="Project notes">${titles.map((title,i)=>`<button role="tab" id="note-tab-${i}" aria-controls="note-content" data-note="${i}" aria-selected="${i===noteIndex}" tabindex="${i===noteIndex?'0':'-1'}"><span>${pad(i+1)}</span><span>${esc(title)}</span></button>`).join('')}</div><div id="note-content" class="note-content" role="tabpanel" aria-labelledby="note-tab-${noteIndex}"><span class="micro note-code">${pad(noteIndex+1)} / ${esc(p.status||'WRITE-UP')}</span><h2>${esc(selected?.title||titles[noteIndex])}</h2>${text?`<p class="note-body">${esc(text)}</p>`:`<p class="empty-note">Write-up coming soon<span class="typing-cursor" aria-hidden="true">_</span></p><div class="note-ghost" aria-hidden="true"><span></span><span></span><span></span></div>`}</div><div class="note-end micro"><span>ZX / ${pad(pageIds.indexOf(current)+1)}</span><span>↳ ${p.status||'IN DEVELOPMENT'}</span></div></section>`;}
function project(id){const p=pages[id];return wrapper(id,`<div class="project-space">${photoPane(p)}${notes(p)}</div>`);}
function about(){const p=pages.about;return wrapper('about',`<div class="about-space"><div class="about-image panel"><div class="panel-code"><span>THE PERSON</span><span>ZX</span></div><img src="assets/portrait.jpg" alt="Zac in the ZXTECH studio"><span class="portrait-caption">ZAC ONG ZHI XING</span></div><div class="about-right">${notes({...p,prompts:['About me']},['About me'])}<div class="about-connections">${p.children.map((id,i)=>`<a class="small-node panel" href="#${id}"><span class="micro">${pad(i+1)}</span><strong>${esc(pages[id].title)}</strong><span>↗</span></a>`).join('')}</div></div></div>`);}
function content(){return wrapper('content',`<div class="content-space"><div class="mission-panel panel"><div class="mission-portrait"><img src="assets/portrait.jpg" alt="Zac presenting in the ZXTECH studio"></div><div class="mission-copy"><span class="micro">INFORM / DESIGN / EXCITE / EDUCATE</span><h2>Bring the future<br>to the people.</h2><p>Design, testing, and technology made clearer.</p><p>A decade of explaining, filming, testing, and listening—shaped by industrial design at NUS and experience leading TECHYARD.</p></div></div><div class="content-data"><div class="metrics">${[[channel.experience,'YEARS CREATING'],[channel.subscribers,'SUBSCRIBERS'],['4.79M','CHANNEL VIEWS'],[channel.videos,'VIDEOS PUBLISHED']].map(([value,label],i)=>`<div class="metric panel"><span class="micro">${pad(i+1)} / ${label}</span><strong>${value}</strong><div class="metric-rule" aria-hidden="true"></div></div>`).join('')}</div><a class="source-note" href="${channel.url}" target="_blank" rel="noopener">YOUTUBE SNAPSHOT / ${channel.checked} / ${channel.views} VIEWS ↗</a><div class="data-placeholder panel"><span class="micro">AUDIENCE / WATCH TIME / REACH</span><p>More analytics to add<span class="typing-cursor" aria-hidden="true">_</span></p></div></div></div>`,`<span class="micro">SEVEN FILMS / ONE JOURNEY</span><a class="sequence-link" href="#video-headphones"><span><small>01 / 07 — PUTTING MY VISION TO WORK</small><strong>Headphones, redesigned</strong></span><b>→</b></a>`);}
function video(id){const p=pages[id],next=videos[p.index+1];return wrapper(id,`<div class="video-space"><div class="film-unit panel"><div class="panel-code"><span>${pad(p.index+1)} / 07 — ${esc(p.sub)}</span><span>${p.year}</span></div><div class="video-screen" id="video-player"><button class="play-video" data-video="${p.id}" aria-label="Play ${esc(p.title)}"><img src="assets/${p.id}.jpg" alt="${esc(p.title)} thumbnail"><span class="play-disc"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="m8 4 13 8-13 8Z" fill="currentColor"/></svg></span><span class="play-label">PLAY FILM ↗</span></button></div><div class="film-caption"><span>${esc(p.title)}</span><a href="https://www.youtube.com/watch?v=${p.id}" target="_blank" rel="noopener">YOUTUBE ↗</a></div></div><aside class="film-side panel"><span class="film-index">${pad(p.index+1)}<small>/07</small></span><span class="micro">${esc(p.sub)}</span><h2>${esc(p.title)}</h2><p class="empty-note">Behind this film<br>Write-up coming soon_</p><div class="film-progress">${videos.map((_,i)=>`<span class="${i<=p.index?'done':''}"></span>`).join('')}</div></aside></div>`,`<a class="back-link" href="#${p.index?videos[p.index-1].slug:'content'}">← ${p.index?'PREVIOUS FILM':'CONTENT CREATION'}</a><a class="sequence-link" href="#${next?next.slug:'content'}"><span><small>${next?`UP NEXT / ${pad(p.index+2)} OF 07`:'SEQUENCE COMPLETE'}</small><strong>${next?esc(next.short):'Back to Content Creation'}</strong></span><b>→</b></a>`);}

function collectMap(){
 const nodes=[{id:'home',title:'Zac Ong Zhi Xing',x:930,y:0,w:260,h:96,root:true}],edges=[];
 const add=(id,x,y)=>{const p=pages[id];nodes.push({id,title:p.short||p.title,x,y,w:260,h:96,sub:p.sub});};
 add('about',0,250);edges.push(['home','about']);pages.about.children.forEach((id,i)=>{add(id,0,450+i*145);edges.push(['about',id]);});
 add('career',340,250);edges.push(['home','career']);pages.career.children.forEach((id,i)=>{add(id,340,450+i*145);edges.push(['career',id]);});
 add('design',1120,250);edges.push(['home','design']);pages.design.children.forEach((id,i)=>{const x=760+i*360;add(id,x,450);edges.push(['design',id]);pages[id].children.forEach((child,j)=>{add(child,x,640+j*145);edges.push([id,child]);});});
 add('content',1920,250);edges.push(['home','content']);videos.forEach((v,i)=>{add(v.slug,1920,450+i*145);edges.push([i?videos[i-1].slug:'content',v.slug]);});return {nodes,edges};
}
const graph=collectMap();
function overview(){scene.innerHTML=`<div class="map-view"><div class="map-heading"><span class="micro">ZX / 32 NODES</span><h1>ARCHIVE / GLOBAL VIEW</h1><p>Drag to move · Scroll to zoom · Select any node</p></div><div class="graph-stage" id="graph-stage">${graph.nodes.map(n=>`<a href="#${n.id}" class="graph-node ${n.root?'graph-root':''} ${n.id===previous?'selected':''}" style="left:${n.x}px;top:${n.y}px;width:${n.w}px;height:${n.h}px"><span class="port"></span><strong>${esc(n.title)}</strong><span class="micro">${n.root?'FUTURIST':esc(n.sub||'')}</span></a>`).join('')}</div><div class="map-controls"><button id="zoom-out" aria-label="Zoom out">−</button><span id="zoom-label">100%</span><button id="zoom-in" aria-label="Zoom in">+</button><button id="fit-map">FIT ALL</button><button id="map-return">RETURN ↗</button></div></div>`;setupMap();}
function drawMap(){const st=$('#graph-stage');if(!st)return;st.style.transform=`translate(${mapState.x}px,${mapState.y}px) scale(${mapState.scale})`;$('#zoom-label').textContent=Math.round(mapState.scale*100)+'%';}
function fitMap(){const w=viewport.clientWidth,h=viewport.clientHeight;const minX=-60,maxX=2240,minY=-120,maxY=1490;const scale=Math.min((w-70)/(maxX-minX),(h-160)/(maxY-minY),.65);mapState={scale,x:(w-(maxX+minX)*scale)/2,y:100+(h-150-(maxY+minY)*scale)/2};drawMap();}
function zoom(factor,cx=viewport.clientWidth/2,cy=viewport.clientHeight/2){const old=mapState.scale,scale=Math.max(.075,Math.min(1.6,old*factor));mapState.x=cx-(cx-mapState.x)*scale/old;mapState.y=cy-(cy-mapState.y)*scale/old;mapState.scale=scale;drawMap();}
function setupMap(){fitMap();const surface=$('.map-view');let points=new Map(),drag=null,moved=false;
 $('#zoom-in').onclick=()=>zoom(1.35);$('#zoom-out').onclick=()=>zoom(1/1.35);$('#fit-map').onclick=fitMap;$('#map-return').onclick=()=>location.hash=previous==='map'?'home':previous;
 surface.addEventListener('wheel',e=>{e.preventDefault();const r=surface.getBoundingClientRect();zoom(Math.exp(-e.deltaY*.0015),e.clientX-r.left,e.clientY-r.top);},{passive:false});
 surface.addEventListener('pointerdown',e=>{if(e.target.closest('.map-controls'))return;points.set(e.pointerId,{x:e.clientX,y:e.clientY});drag={x:e.clientX,y:e.clientY,tx:mapState.x,ty:mapState.y};moved=false;});
 surface.addEventListener('pointermove',e=>{if(!points.has(e.pointerId))return;const prev=points.get(e.pointerId);if(points.size===2){const other=[...points.entries()].find(([id])=>id!==e.pointerId)[1];const old=Math.hypot(prev.x-other.x,prev.y-other.y);const now=Math.hypot(e.clientX-other.x,e.clientY-other.y);const r=surface.getBoundingClientRect();zoom(now/old,(e.clientX+other.x)/2-r.left,(e.clientY+other.y)/2-r.top);moved=true;}else if(drag){const dx=e.clientX-drag.x,dy=e.clientY-drag.y;if(Math.abs(dx)+Math.abs(dy)>5){moved=true;surface.setPointerCapture(e.pointerId);mapState.x=drag.tx+dx;mapState.y=drag.ty+dy;drawMap();}}points.set(e.pointerId,{x:e.clientX,y:e.clientY});});
 const end=e=>{points.delete(e.pointerId);drag=null;};surface.addEventListener('pointerup',end);surface.addEventListener('pointercancel',end);surface.addEventListener('click',e=>{if(moved&&!e.target.closest('.map-controls')){e.preventDefault();moved=false;}},true);
}
const modal=document.createElement('dialog');modal.className='lightbox';modal.setAttribute('aria-label','Image viewer');modal.innerHTML='<button class="close-lightbox" aria-label="Close image">CLOSE ×</button><figure><img alt=""><figcaption></figcaption></figure>';document.body.append(modal);modal.querySelector('button').onclick=()=>modal.close();modal.onclick=e=>{if(e.target===modal)modal.close();};
let spreadObserver;
function mountSpread(){
 const spread=scene.querySelector('.card-spread');if(!spread)return;
 const cards=[...spread.querySelectorAll('.branch-card')];let positions=[],pointer=-1,focus=-1;
 const move=()=>{
  const active=pointer>=0?pointer:focus,target=positions[active];
  cards.forEach((el,i)=>{
   const p=positions[i];if(!p)return;let dx=0,dy=0;
   if(target&&i!==active){const vx=p.x-target.x,vy=p.y-target.y,length=Math.hypot(vx,vy)||1,shift=Math.min(30,p.w*.09);dx=vx/length*shift;dy=vy/length*shift;}
   el.style.setProperty('--push-x',dx+'px');el.style.setProperty('--push-y',dy+'px');
   el.classList.toggle('card-active',i===active);el.classList.toggle('card-neighbour',active>=0&&i!==active);
  });
 };
 const layout=()=>{
  positions=spreadLayout(cards.length,spread.clientWidth,spread.clientHeight);
  cards.forEach((el,i)=>{const p=positions[i];el.style.left=p.x+'px';el.style.top=p.y+'px';el.style.setProperty('--card-w',p.w+'px');el.style.setProperty('--card-h',p.h+'px');});move();
 };
 spread.addEventListener('pointerover',e=>{const el=e.target.closest('.branch-card');if(el){pointer=cards.indexOf(el);move();}});
 spread.addEventListener('pointerout',e=>{const el=e.target.closest('.branch-card');if(el&&!el.contains(e.relatedTarget)){pointer=-1;move();}});
 spread.addEventListener('focusin',e=>{focus=cards.indexOf(e.target.closest('.branch-card'));move();});
 spread.addEventListener('focusout',()=>{focus=-1;move();});
 layout();spreadObserver=new ResizeObserver(layout);spreadObserver.observe(spread);
}
function render(){spreadObserver?.disconnect();if(current==='map'){overview();return;}const id=current;scene.innerHTML=id==='home'?home():id==='about'?about():id==='content'?content():pages[id].kind==='branch'?branch(id):pages[id].kind==='video'?video(id):project(id);mountSpread();}
function updateMedia(){const p=pages[current],items=mediaItems(p);if(!items.length)return;mediaIndex=(mediaIndex+items.length)%items.length;const active=scene.querySelector('.media-panel');active.outerHTML=photoPane(p);}
function chooseNote(index,focus=false){const p=current==='about'?{...pages.about,prompts:['About me']}:pages[current];noteIndex=index;scene.querySelector('.note-panel').outerHTML=notes(p,p.prompts);if(focus)scene.querySelector(`[data-note="${index}"]`).focus();}
scene.addEventListener('click',e=>{
 const image=e.target.closest('.image-open');if(image){modal.querySelector('img').src=image.dataset.src;modal.querySelector('img').alt=image.dataset.caption;modal.querySelector('figcaption').textContent=image.dataset.caption;modal.showModal();}
 const step=e.target.closest('[data-image-step]'),thumb=e.target.closest('[data-image-index]'),note=e.target.closest('[data-note]');
 if(step){mediaIndex+=Number(step.dataset.imageStep);updateMedia();}if(thumb){mediaIndex=Number(thumb.dataset.imageIndex);updateMedia();}if(note)chooseNote(Number(note.dataset.note),true);
 const play=e.target.closest('.play-video');if(play){$('#video-player').innerHTML=`<iframe src="https://www.youtube-nocookie.com/embed/${play.dataset.video}?autoplay=1&rel=0" title="${esc(pages[current].title)}" allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share" referrerpolicy="strict-origin-when-cross-origin" allowfullscreen></iframe>`;}
});
let navTimer;
function route(){let id;try{id=decodeURIComponent(location.hash.slice(1))||'home';}catch{id='home';}if(!['home','map'].includes(id)&&!pages[id]){location.replace('#home');return;}if(current!=='map'&&id==='map')previous=current;current=id;mediaIndex=0;noteIndex=0;scene.style.setProperty('--enter-x',entry.x+'px');scene.style.setProperty('--enter-y',entry.y+'px');scene.className=id==='home'?'home-scene':id==='map'?'map-scene':'page-scene';render();$('#home').classList.toggle('active',id==='home');$('#map').classList.toggle('active',id==='map');$('#back').disabled=id==='home';$('#location').textContent=id==='home'?'ROOT / 00':id==='map'?'GLOBAL MAP':pad(pageIds.indexOf(id)+1)+' / '+(pages[id].short||pages[id].title).toUpperCase();$('#hint').textContent=id==='map'?'DRAG / ZOOM / EXPLORE':id==='home'?'CHOOSE A DIRECTION':'ESC BACK / H HOME / M MAP';document.title=id==='home'?'ZX — Zac Ong Zhi Xing':id==='map'?'Global Map — ZX':pages[id].title+' — ZX';mesh.navigate(id);if(id!=='home'&&id!=='map')requestAnimationFrame(()=>scene.querySelector('h1')?.focus({preventScroll:true}));}
function navigate(id,dir=1){if(id===current)return;clearTimeout(navTimer);entry={x:dir*100,y:0};if(matchMedia('(prefers-reduced-motion: reduce)').matches){location.hash=id;return;}const el=scene.firstElementChild;el?.animate([{opacity:1,transform:'translateX(0)'},{opacity:0,transform:`translateX(${-dir*80}px)`}],{duration:190,easing:'cubic-bezier(.3,0,.8,1)',fill:'forwards'});navTimer=setTimeout(()=>{location.hash=id;},190);}
scene.addEventListener('click',e=>{const a=e.target.closest('a[href^="#"]');if(!a||e.defaultPrevented||e.metaKey||e.ctrlKey||e.shiftKey)return;e.preventDefault();const id=a.getAttribute('href').slice(1);navigate(id,a.getBoundingClientRect().x<innerWidth/2?-1:1);});
$('.logo').onclick=e=>{e.preventDefault();navigate('home',-1);};$('.skip').onclick=e=>{e.preventDefault();$('#content').focus();};$('#home').onclick=()=>navigate('home',-1);$('#back').onclick=()=>navigate(current==='map'?previous:(pages[current]?.parent||'home'),-1);$('#map').onclick=()=>navigate(current==='map'?previous:'map',1);
window.addEventListener('keydown',e=>{if(e.ctrlKey||e.metaKey||e.altKey||e.target.matches('input,textarea,select,[contenteditable]')||modal.open)return;if(e.target.matches('[data-note]')&&['ArrowLeft','ArrowRight'].includes(e.key)){e.preventDefault();const count=scene.querySelectorAll('[data-note]').length;chooseNote((noteIndex+(e.key==='ArrowRight'?1:-1)+count)%count,true);return;}const k=e.key.toLowerCase();if(k==='h'){e.preventDefault();navigate('home',-1);}else if(k==='m'){e.preventDefault();navigate(current==='map'?previous:'map');}else if(k==='escape'&&current!=='home'){e.preventDefault();$('#back').click();}else if(current==='map'){if(e.key==='+')zoom(1.25);if(e.key==='-')zoom(.8);if(e.key==='0')fitMap();}else if(['ArrowLeft','ArrowRight'].includes(e.key)){const links=scene.querySelectorAll('.slide-bottom a');const a=e.key==='ArrowRight'?links[links.length-1]:links[0];if(a){e.preventDefault();navigate(a.hash.slice(1),e.key==='ArrowRight'?1:-1);}}});
let resizeTimer;window.addEventListener('resize',()=>{clearTimeout(resizeTimer);resizeTimer=setTimeout(()=>{if(current==='map')fitMap();},150);});window.addEventListener('hashchange',route);route();
